// Кожен рядок може мати координати в origin, destination, або обох —
// розкладаємо на окремі завдання геокодування по одному на поле.
// Зони (HOME-OFFICE, CLIENT-*, SUPPLIER-*) сюди не потрапляють: SQL-фільтр
// у попередній ноді пропускає все, що не виглядає як "лат, лон".
const COORD = /^(-?\d+\.\d+),\s*(-?\d+\.\d+)$/;
const out = [];
for (const item of $input.all()) {
  const row = item.json;
  for (const field of ['origin_address', 'destination_address']) {
    const m = COORD.exec((row[field] || '').trim());
    if (m) out.push({ json: { trip_id: row.id, field, lat: m[1], lon: m[2] } });
  }
}
return out;

// Короткий рядок для картки: номер+вулиця, район. Повний display_name
// із Nominatim задовгий і містить зайве (місто/провінція/індекс/країна).
// Без номера будинку OSM повертає лише вулицю — це все одно краще за
// голі координати, але саме вулицю, а не випадкову сусідню будівлю.
const req = $('Розкласти на завдання').item.json;
const addr = ($json && $json.address) || {};

const parts = [];
if (addr.house_number && addr.road) parts.push(`${addr.house_number} ${addr.road}`);
else if (addr.road) parts.push(addr.road);

const suburb = addr.suburb || addr.village || addr.town || addr.city_district || addr.neighbourhood;
if (suburb) parts.push(suburb);

return [{ json: {
  trip_id: req.trip_id,
  field: req.field,
  short_address: parts.length ? parts.join(', ') : null
} }];
